363	.step-item.step-agent_done   { border-left: 3px solid var(--success); }
364	.step-item.step-critique_done { border-left: 3px solid #a78bfa; }
365	.step-item.step-error        { border-left: 3px solid var(--danger); }
366	
367	.step-icon { font-size: 1rem; flex-shrink: 0; margin-top: 1px; }
368	.step-body { flex: 1; min-width: 0; }
369	.step-meta {
370	  display: flex;
371	  align-items: center;
372	  gap: 8px;
373	  margin-bottom: 2px;
374	}
375	.step-agent-tag {
376	  font-size: 0.72rem;
377	  font-weight: 700;
378	  letter-spacing: 0.05em;
379	  text-transform: uppercase;
380	  color: var(--accent-light);
381	  background: rgba(79,142,247,0.12);
382	  padding: 1px 7px;
383	  border-radius: 4px;
384	}
385	.step-time {
386	  font-size: 0.72rem;
387	  color: var(--text-muted);
388	  font-family: var(--font-mono);
389	}
390	.step-message {
391	  font-size: 0.85rem;
392	  color: var(--text-secondary);
393	  overflow-wrap: break-word;
394	}
395	
396	/* ── Scrollbar ───────────────────────────────────────────────────── */
397	::-webkit-scrollbar { width: 6px; }
398	::-webkit-scrollbar-track { background: var(--bg-primary); }
399	::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
400	::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }
401	
402	/* ── Responsive ──────────────────────────────────────────────────── */
403	@media (max-width: 640px) {
404	  .ticker-row { flex-direction: column; }
405	  .ticker-row input#tickerInput { flex: unset; width: 100%; }
406	  .message-bubble { max-width: 95%; }
407	  .tabs-nav { padding: 0 12px; }
408	  .main-content { padding: 0 12px 60px; }
409	}
