164	// ── Event router ──────────────────────────────────────────────────────────────
165	const EVENT_ICONS = {
166	  session_ready:    '🟢',
167	  validation_error: '❌',
168	  agent_start:      '🚀',
169	  agent_done:       '✅',
170	  tool_call:        '🔧',
171	  tool_result:      '📦',
172	  synthesis_start:  '🔗',
173	  synthesis_done:   '✅',
174	  critique_start:   '🔎',
175	  critique_done:    '🏷️',
176	  rerun_start:      '🔄',
177	  final_output:     '📊',
178	  abstain:          '⚠️',
179	  error:            '🚨',
