190	      setStatus('🟢', message);
191	      break;
192	
193	    case 'validation_error':
194	      showTickerError(message);
195	      setAnalysisRunning(false);
196	      setStatus('❌', 'Invalid ticker entered.');
197	      break;
198	
199	    case 'agent_start':
200	    case 'synthesis_start':
201	    case 'critique_start':
202	    case 'rerun_start':
203	      setStatus(EVENT_ICONS[event_type] || '⏳', message);
204	      break;
205	
206	    case 'agent_done':
207	    case 'synthesis_done':
208	    case 'critique_done':
209	      setStatus(EVENT_ICONS[event_type] || '✅', message);
