266	function addMessage(role, text) {
267	  const isAgent = role === 'agent';
268	  const div = document.createElement('div');
269	  div.className = `message ${isAgent ? 'agent-message' : 'user-message'}`;
270	  div.innerHTML = `
271	    <div class="message-avatar">${isAgent ? '🤖' : '👤'}</div>
272	    <div class="message-bubble">${isAgent ? renderMarkdown(text) : escapeHtml(text)}</div>
273	  `;
274	  messagesContainer.appendChild(div);
275	  scrollToBottom(messagesContainer);
276	}
277	
278	function addAgentMessage(markdown, payload) {
279	  const div = document.createElement('div');
280	  div.className = 'message agent-message';
281	
282	  let figuresHtml = '';
283	  if (payload && payload.figures && payload.figures.length > 0) {
284	    figuresHtml = payload.figures.map(b64 =>
285	      `<img class="chart-img" src="data:image/png;base64,${b64}" alt="Analysis chart" />`
286	    ).join('');
287	  }
288	
289	  div.innerHTML = `
290	    <div class="message-avatar">🤖</div>
291	    <div class="message-bubble">
292	      ${renderMarkdown(markdown)}
293	      ${figuresHtml}
294	    </div>
295	  `;
296	  messagesContainer.appendChild(div);
297	  scrollToBottom(messagesContainer);
298	}
299	
300	function addStep(event_type, agent_name, message, timestamp, payload) {
301	  // Remove empty placeholder
302	  if (stepsEmpty && stepsEmpty.parentNode) {
303	    stepsEmpty.parentNode.removeChild(stepsEmpty);
304	  }
305	
306	  stepCount++;
307	  stepBadge.textContent = stepCount;
308	
309	  const icon = EVENT_ICONS[event_type] || 'ℹ️';
310	  const time = timestamp ? new Date(timestamp).toLocaleTimeString() : '';
311	
312	  // Build rich detail panel for specific event types
313	  let detailHtml = '';
314	  if (event_type === 'agent_done' && payload && payload.claims) {
315	    detailHtml = buildSpecialistDetail(payload);
316	  } else if (event_type === 'synthesis_done' && payload) {
317	    detailHtml = buildSynthesisDetail(payload);
318	  } else if (event_type === 'critique_done' && payload && payload.critique) {
319	    detailHtml = buildCritiqueDetail(payload.critique);
320	  }
321	
322	  const item = document.createElement('div');
323	  item.className = `step-item step-${event_type}`;
324	  item.innerHTML = `
325	    <div class="step-icon">${icon}</div>
326	    <div class="step-body">
327	      <div class="step-meta">
328	        ${agent_name ? `<span class="step-agent-tag">${escapeHtml(agent_name)}</span>` : ''}
329	        ${time ? `<span class="step-time">${time}</span>` : ''}
330	      </div>
331	      <div class="step-message">${escapeHtml(message)}</div>
332	      ${detailHtml ? `<details class="step-detail"><summary>View details</summary><div class="step-detail-content">${detailHtml}</div></details>` : ''}
333	    </div>
334	  `;
335	  stepsContainer.appendChild(item);
336	  scrollToBottom(stepsContainer);
337	}
338	
339	// ── Rich detail builders ──────────────────────────────────────────────────────
340	
341	/** Returns a safe http/https URL or null. */
342	function safeUrl(url) {
343	  if (!url || typeof url !== 'string') return null;
344	  return (url.startsWith('http://') || url.startsWith('https://')) ? url : null;
345	}
346	
347	function buildSpecialistDetail(payload) {
348	  const pct = payload.confidence !== undefined ? Math.round(payload.confidence * 100) : 0;
349	  const confColor = pct >= 70 ? 'var(--success)' : pct >= 40 ? 'var(--warning)' : 'var(--danger)';
350	
351	  let html = '';
352	
353	  // Confidence
354	  html += `<div class="step-dl-row">
355	    <span class="step-dl-label">Confidence</span>
356	    <div class="step-conf-bar"><div class="step-conf-fill" style="width:${pct}%;background:${confColor}"></div></div>
357	    <span class="step-conf-pct" style="color:${confColor}">${pct}%</span>
358	  </div>`;
359	
360	  // Claims
361	  if (payload.claims && payload.claims.length > 0) {
362	    html += `<div class="step-dl-label">Key Claims</div><ul class="step-claims">`;
363	    payload.claims.forEach(c => { html += `<li>${escapeHtml(c)}</li>`; });
364	    html += `</ul>`;
365	  }
366	
367	  // Evidence
368	  if (payload.evidence && payload.evidence.length > 0) {
369	    html += `<div class="step-dl-label">Evidence &amp; Sources</div>`;
370	    payload.evidence.forEach(ev => {
371	      const link = safeUrl(ev.source_url);
372	      const filingId = ev.filing_identifier;
373	      html += `<div class="step-evidence-item">
374	        <span class="step-source-badge">${escapeHtml(ev.source_type || '')}</span>
375	        <span class="step-evidence-text">${escapeHtml((ev.text || '').slice(0, 220))}${(ev.text || '').length > 220 ? '…' : ''}</span>
376	        ${link ? `<div><a class="step-source-link" href="${escapeHtml(link)}" target="_blank" rel="noopener noreferrer">${escapeHtml(link)}</a></div>` : ''}
377	        ${!link && filingId ? `<div class="step-filing-id">${escapeHtml(filingId)}</div>` : ''}
378	      </div>`;
379	    });
380	  }
381	
382	  // Failure reason
383	  if (!payload.success && payload.failure_reason) {
384	    html += `<div class="step-failure"><span class="step-dl-label">Failure Reason</span> ${escapeHtml(payload.failure_reason)}</div>`;
385	  }
386	
387	  return html;
388	}
389	
390	function buildSynthesisDetail(payload) {
391	  let html = '';
392	
393	  if (payload.key_hypothesis) {
394	    html += `<div class="step-dl-label">Key Hypothesis</div>
395	    <div class="step-hypothesis">${escapeHtml(payload.key_hypothesis)}</div>`;
396	  }
397	
398	  if (payload.sources && payload.sources.length > 0) {
399	    const shown = payload.sources.slice(0, 10);
400	    const rest  = payload.sources.length - shown.length;
401	    html += `<div class="step-dl-label">Sources (${payload.sources.length})</div><ul class="step-sources">`;
402	    shown.forEach(src => {
403	      const link = safeUrl(src);
404	      html += `<li>${link ? `<a class="step-source-link" href="${escapeHtml(link)}" target="_blank" rel="noopener noreferrer">${escapeHtml(link)}</a>` : escapeHtml(src)}</li>`;
405	    });
406	    if (rest > 0) html += `<li class="step-more">…and ${rest} more</li>`;
407	    html += `</ul>`;
408	  }
409	
410	  if (payload.omitted_specialists && payload.omitted_specialists.length > 0) {
411	    html += `<div class="step-failure"><span class="step-dl-label">Omitted Specialists</span> ${escapeHtml(payload.omitted_specialists.join(', '))}</div>`;
412	  }
413	
414	  return html;
415	}
416	
417	function buildCritiqueDetail(critique) {
418	  if (!critique) return '';
419	
420	  const sevColor = { none: 'var(--success)', low: 'var(--text-secondary)', medium: 'var(--warning)', high: 'var(--danger)' };
421	  const sev = critique.overall_severity || 'none';
422	
423	  let html = `<div class="step-dl-row">
424	    <span class="step-dl-label">Overall Severity</span>
425	    <span class="step-sev-badge" style="color:${sevColor[sev] || 'inherit'}">${sev.toUpperCase()}</span>
426	  </div>`;
427	
428	  if (critique.critique_summary) {
429	    html += `<div class="step-critique-summary">${escapeHtml(critique.critique_summary)}</div>`;
430	  }
431	
432	  if (critique.issues && critique.issues.length > 0) {
433	    html += `<div class="step-dl-label">Issues (${critique.issues.length})</div>`;
434	    critique.issues.forEach(issue => {
435	      const isevColor = sevColor[issue.severity] || 'inherit';
436	      html += `<div class="step-issue-item">
437	        <div class="step-issue-header">
438	          <span class="step-sev-badge" style="color:${isevColor}">${(issue.severity || '').toUpperCase()}</span>
439	          <span class="step-issue-tag">${escapeHtml(issue.tag || '')}</span>
440	          <span class="step-issue-agent">${escapeHtml(issue.affected_specialist || '')}</span>
441	        </div>
442	        <div class="step-issue-quote">"${escapeHtml((issue.quote || '').slice(0, 180))}${(issue.quote || '').length > 180 ? '…' : ''}"</div>
443	        ${issue.suggestion ? `<div class="step-issue-suggestion">${escapeHtml(issue.suggestion)}</div>` : ''}
444	      </div>`;
445	    });
446	  }
447	
448	  return html;
449	}
450	
451	function scrollToBottom(el) {
452	  el.scrollTop = el.scrollHeight;
453	}
454	
455	function escapeHtml(str) {
456	  return String(str)
457	    .replace(/&/g, '&amp;')
458	    .replace(/</g, '&lt;')
459	    .replace(/>/g, '&gt;')
460	    .replace(/"/g, '&quot;');
461	}
462	
463	// ── Init ─────────────────────────────────────────────────────────────────────
464	connect();
465

